32	    public EnnfuProtocolDecoder(Protocol protocol) {
33	        super(protocol);
34	    }
35	
36	    private static final Pattern PATTERN = new GrammarComposer()
37	            .text("Ennfu:")
38	            .number("(d+),")                     // imei
39	            .number("(dd)(dd)(dd).dd,")          // time (hhmmss)
40	            .expression("([AV]),")               // validity
41	            .number("(dd)(dd.d+),")              // latitude
42	            .expression("([NS]),")
43	            .number("(ddd)(dd.d+),")             // longitude
44	            .expression("([EW]),")
45	            .number("(d+.d+)?,")                 // speed
46	            .number("(d+.d+)?,")                 // course
47	            .number("(dd)(dd)(dd),")             // date (ddmmyy)
48	            .number("(d+),")                     // rssi
49	            .number("(d+.d+),")                  // battery
50	            .number("(d+.d+),")                  // battery level
51	            .number("(Vd.dd)")                   // firmware version
52	            .compile();
53	
54	    @Override
55	    protected Object decode(
56	            Channel channel, SocketAddress remoteAddress, Object msg) throws Exception {
57	
58	        FieldCursor parser = new FieldCursor(PATTERN, (String) msg);
59	        if (!parser.matches()) {
60	            return null;
61	        }
62	
63	        UnitSession deviceSession = resolveUnitSession(channel, remoteAddress, parser.next());
64	        if (deviceSession == null) {
65	            return null;
66	        }
67	
68	        Position position = new Position(wireName());
69	        position.setDeviceId(deviceSession.getDeviceId());
70	
71	        DateBuilder dateBuilder = new DateBuilder()
72	                .setTime(parser.nextInt(), parser.nextInt(), parser.nextInt());
73	
74	        position.setValid(parser.next().equals("A"));
75	        position.setLatitude(parser.nextCoordinate());
76	        position.setLongitude(parser.nextCoordinate());
77	        position.setSpeed(parser.nextDouble(0));
78	        position.setCourse(parser.nextDouble(0));
79	
80	        dateBuilder.setDateReverse(parser.nextInt(), parser.nextInt(), parser.nextInt());
81	        position.setTime(dateBuilder.getDate());
82	
83	        position.set(Position.KEY_RSSI, parser.nextInt());
84	        position.set(Position.KEY_BATTERY, parser.nextDouble());
85	        position.set(Position.KEY_BATTERY_LEVEL, parser.nextDouble());
86	        position.set(Position.KEY_VERSION_FW, parser.next());
