16	package org.traccar.helper;
17	
18	import java.util.Date;
19	import java.util.TimeZone;
20	import java.util.regex.Matcher;
21	import java.util.regex.Pattern;
22	
23	public class FieldCursor {
24	
25	    private int position;
26	    private final Matcher matcher;
27	
28	    public FieldCursor(Pattern pattern, String input) {
29	        matcher = pattern.matcher(input);
30	    }
31	
32	    public boolean matches() {
33	        position = 1;
34	        return matcher.matches();
35	    }
36	
37	    public boolean find() {
38	        position = 1;
39	        return matcher.find();
40	    }
41	
42	    public void skip(int number) {
43	        position += number;
44	    }
45	
46	    public boolean hasNext() {
47	        return hasNext(1);
48	    }
49	
50	    public boolean hasNext(int number) {
51	        for (int i = position; i < position + number; i++) {
52	            String value = matcher.group(i);
53	            if (value == null || value.isEmpty()) {
54	                position += number;
55	                return false;
56	            }
57	        }
58	        return true;
59	    }
60	
61	    public boolean hasNextAny(int number) {
62	        for (int i = position; i < position + number; i++) {
63	            String value = matcher.group(i);
64	            if (value != null && !value.isEmpty()) {
65	                return true;
66	            }
67	        }
68	        position += number;
69	        return false;
70	    }
71	
72	    public String next() {
73	        return matcher.group(position++);
74	    }
75	
76	    public Integer nextInt() {
77	        if (hasNext()) {
78	            return Integer.parseInt(next());
79	        } else {
80	            return null;
81	        }
82	    }
83	
84	    public int nextInt(int defaultValue) {
85	        if (hasNext()) {
86	            return Integer.parseInt(next());
87	        } else {
88	            return defaultValue;
89	        }
90	    }
91	
92	    public Integer nextHexInt() {
93	        if (hasNext()) {
94	            return Integer.parseInt(next(), 16);
95	        } else {
96	            return null;
97	        }
98	    }
99	
100	    public int nextHexInt(int defaultValue) {
101	        if (hasNext()) {
